def gf_mul(a, b):
    result = 0
    while b:
        if b & 1:
            result = result ^ a
        a = a << 1
        if a & 256:
            a = a ^ 283
        b = b >> 1
    return result & 255


def gf_pow(a, power):
    result = 1
    while power:
        if power & 1:
            result = gf_mul(result, a)
        a = gf_mul(a, a)
        power = power >> 1
    return result


def rotate_byte(value, amount):
    return ((value << amount) | (value >> (8 - amount))) & 255


def init():
    sbox = list()
    for value in range(256):
        if value == 0:
            inverse = 0
        else:
            inverse = gf_pow(value, 254)
        mapped = inverse ^ rotate_byte(inverse, 1) ^ rotate_byte(inverse, 2) ^ rotate_byte(inverse, 3) ^ rotate_byte(inverse, 4) ^ 99
        sbox.append(mapped & 255)
    return dict(sbox=sbox)


def step(state, inputs):
    state_in = int(inputs.get("state_in", 0)) & ((1 << 128) - 1)
    round_key = int(inputs.get("round_key", 0)) & ((1 << 128) - 1)
    final_round = int(inputs.get("final_round", 0)) & 1
    sbox = state.get("sbox")

    substituted = list()
    for n in range(16):
        shift = 120 - 8 * n
        substituted.append(sbox[(state_in >> shift) & 255])

    shifted = list()
    for n in range(16):
        row = n % 4
        column = n // 4
        old_column = (column + row) % 4
        shifted.append(substituted[row + 4 * old_column])

    if final_round == 0:
        mixed = list()
        for column in range(4):
            a0 = shifted[4 * column]
            a1 = shifted[4 * column + 1]
            a2 = shifted[4 * column + 2]
            a3 = shifted[4 * column + 3]
            mixed.append(gf_mul(2, a0) ^ gf_mul(3, a1) ^ a2 ^ a3)
            mixed.append(a0 ^ gf_mul(2, a1) ^ gf_mul(3, a2) ^ a3)
            mixed.append(a0 ^ a1 ^ gf_mul(2, a2) ^ gf_mul(3, a3))
            mixed.append(gf_mul(3, a0) ^ a1 ^ a2 ^ gf_mul(2, a3))
    else:
        mixed = shifted

    result = 0
    for n in range(16):
        result = (result << 8) | mixed[n]

    outputs = dict(state_out=(result ^ round_key) & ((1 << 128) - 1))
    return state, outputs
